package com.tallerexpress.model;
import java.math.BigDecimal; import java.time.LocalDateTime;
public class SparePart {
    private int id,stockTotal,stockAvailable; private String referenceCode,name,category,supplier; private BigDecimal unitPrice; private boolean active; private LocalDateTime createdAt;
    public SparePart() {} public SparePart(int id,String referenceCode,String name,String category,String supplier,int stockTotal,int stockAvailable,BigDecimal unitPrice,boolean active,LocalDateTime createdAt){this.id=id;this.referenceCode=referenceCode;this.name=name;this.category=category;this.supplier=supplier;this.stockTotal=stockTotal;this.stockAvailable=stockAvailable;this.unitPrice=unitPrice;this.active=active;this.createdAt=createdAt;}
    public int getId(){return id;} public void setId(int v){id=v;} public String getReferenceCode(){return referenceCode;} public void setReferenceCode(String v){referenceCode=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getSupplier(){return supplier;} public void setSupplier(String v){supplier=v;} public int getStockTotal(){return stockTotal;} public void setStockTotal(int v){stockTotal=v;} public int getStockAvailable(){return stockAvailable;} public void setStockAvailable(int v){stockAvailable=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
}
